-- Rehearse explicit reversal and reapplication; never commit this QA transaction.
\set ON_ERROR_STOP on
begin isolation level repeatable read; set local timezone='America/Sao_Paulo'; set local statement_timeout='25s'; set local lock_timeout='1s'; create temp table v298_restore_before on commit drop as select oid,pg_get_functiondef(oid) d,proowner,proacl,proconfig,prosecdef,provolatile from pg_proc where oid in('public.lts_expense_rows_pre_categories_v290(uuid,date,date)'::regprocedure,'public.lts_expense_rows_v230_baseline(uuid,date,date)'::regprocedure,'public.lts_c6_cycle_identity_v269(uuid)'::regprocedure,'public.lts_card_workbook_bank_rows_v1(uuid)'::regprocedure,'public.lts_card_cycles_v226(uuid)'::regprocedure); create temp table v298_source_restore_before on commit drop as select jsonb_object_agg(name,summary) from (select 'evento_base' name,jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) summary from (select md5(to_jsonb(r)::text) h from public.evento_base r where usuario_id=public.lts_open_finance_pilot_owner_v1()) q union all select 'financial_events',jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(r)::text) h from public.financial_events r where user_id=public.lts_open_finance_pilot_owner_v1()) q union all select 'staging',jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(r)::text) h from public.lts_open_finance_staging r where user_id=public.lts_open_finance_pilot_owner_v1()) q union all select 'decisions',jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(r)::text) h from public.lts_v178_review_decision r where user_id=public.lts_open_finance_pilot_owner_v1()) q union all select 'workbook',jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(r)::text) h from public.lts_card_workbook_evidence_v226 r where user_id=public.lts_open_finance_pilot_owner_v1()) q) summaries; \ir ../patches/v298/rollback_review_reuse.sql
\ir ../patches/v298/review_source_lookup.sql
\ir ../patches/v298/review_normalization.sql
\ir ../patches/v298/c6_reuse.sql
\ir ../patches/v298/workbook_unchanged_row.sql
\ir ../patches/v298/card_cycle_reuse.sql
 do $$begin if exists(select 1 from v298_restore_before b join pg_proc p using(oid) where pg_get_functiondef(p.oid) is distinct from b.d or p.proowner<>b.proowner or p.proacl is distinct from b.proacl or p.proconfig is distinct from b.proconfig or p.prosecdef<>b.prosecdef or p.provolatile<>b.provolatile) then raise exception 'V298 reversal/reapply changed definition or permissions'; end if;end$$; create temp table v298_source_restore_after on commit drop as select jsonb_object_agg(name,summary) from (select 'evento_base' name,jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) summary from (select md5(to_jsonb(r)::text) h from public.evento_base r where usuario_id=public.lts_open_finance_pilot_owner_v1()) q union all select 'financial_events',jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(r)::text) h from public.financial_events r where user_id=public.lts_open_finance_pilot_owner_v1()) q union all select 'staging',jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(r)::text) h from public.lts_open_finance_staging r where user_id=public.lts_open_finance_pilot_owner_v1()) q union all select 'decisions',jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(r)::text) h from public.lts_v178_review_decision r where user_id=public.lts_open_finance_pilot_owner_v1()) q union all select 'workbook',jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(h,'' order by h),''))) from(select md5(to_jsonb(r)::text) h from public.lts_card_workbook_evidence_v226 r where user_id=public.lts_open_finance_pilot_owner_v1()) q) summaries; do $$begin if (select jsonb_object_agg from v298_source_restore_before) is distinct from (select jsonb_object_agg from v298_source_restore_after) then raise exception 'V298 reversal changed financial sources';end if;end$$; select 'PASS' status,count(*) restored_and_reapplied_functions from v298_restore_before; rollback;
